//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::float32::isinf`; the
//! native twin is `benches/native/Bench/Float32Isinf.lean`.

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::float32;
use lean_runtime_bench::{run, step, SEED};

#[allow(unused_variables)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = acc.wrapping_add(float32::isinf(
            ((-1000000.0 + ((x >> 11) as f64 * (1.0 / 9007199254740992.0)) * 2000000.0) as f32),
        ) as u64);
    }
    acc as u64
}

fn main() {
    run(|| (), kernel)
}
